#include <stdio.h>
#include <string.h>
#include <ctype.h>

static void url_decode(const char *src, size_t slen, char *dst)
{
    size_t i = 0, j = 0;
    while (i < slen) {
        char c = src[i];
        if (c == '+') {
            dst[j++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < slen && isxdigit((unsigned char)src[i+1]) && isxdigit((unsigned char)src[i+2])) {
            char hi = src[i+1];
            char lo = src[i+2];
            int val = (isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10));
            val = (val << 4) + (isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10));
            dst[j++] = (char)val;
            i += 3;
        } else {
            dst[j++] = c;
            ++i;
        }
    }
    dst[j] = '\0';
}

int main(void)
{
    char line[2048];
    char key[1024];
    char val[1024];
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }
    size_t len = strlen(line);
    if (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
        if (len > 0 && line[len-1] == '\r')
            line[--len] = '\0';
    }
    char *p = line;
    while (*p) {
        char *eq = strchr(p, '=');
        char *amp = strchr(p, '&');
        if (!amp) amp = p + strlen(p);
        if (eq && eq < amp) {
            url_decode(p, (size_t)(eq - p), key);
            url_decode(eq + 1, (size_t)(amp - (eq + 1)), val);
        } else {
            url_decode(p, (size_t)(amp - p), key);
            val[0] = '\0';
        }
        printf("%s=%s\n", key, val);
        if (*amp == '&')
            p = amp + 1;
        else
            break;
    }
    return 0;
}
